mapper.select:
select
,
,
coalesce(
    (select 'ADMIN' from admin x where x.username = d.applicant or x.name = d.applicant limit 1),
    (select 'DEV' from dev x where x.deleted = 0 and (x.username = d.applicant or x.name = d.applicant) limit 1),
    (select 'OPS' from ops x where x.deleted = 0 and (x.username = d.applicant or x.name = d.applicant) limit 1)
) as applicant_role,
coalesce(
    (select 'ADMIN' from admin x where x.username = d.approver or x.name = d.approver limit 1),
    (select 'DEV' from dev x where x.deleted = 0 and (x.username = d.approver or x.name = d.approver) limit 1),
    (select 'OPS' from ops x where x.deleted = 0 and (x.username = d.approver or x.name = d.approver) limit 1)
) as approver_role


    d.deleted = 0
     and d.id= #{id}
     and d.deploy_no like concat('%', #{deployNo}, '%')
     and d.status= #{status}
     and d.app_id= #{appId}
     and d.server_id= #{serverId}
     and d.deploy_type= #{deployType}
     and d.applicant like concat('%', #{applicant}, '%')
     and d.approver like concat('%', #{approver}, '%')
     and d.apply_time >= #{startTime}
     and d.apply_time <= #{endTime}

order by d.id desc

mapper.update:
update deploy
set deleted = 1
where id = #{id}
